"use client";

import * as React from "react";
import { Dialog as SheetPrimitive } from "@base-ui/react/dialog";
import { cva, type VariantProps } from "class-variance-authority";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { buttonVariants } from "@/components/ui/button";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Bold retail Sheet root: a panel that slides in from one edge, such as the bag or the filters. */
const Sheet = SheetPrimitive.Root;

/** The control that opens the sheet. */
const SheetTrigger = SheetPrimitive.Trigger;

/** Closes the sheet. Use it to wrap a Cancel or Done button. */
const SheetClose = SheetPrimitive.Close;

/** Moves the sheet to the end of the document body. */
const SheetPortal = SheetPrimitive.Portal;

/** Bold retail sheet scrim: a half-tone black veil over the page. */
const SheetOverlay = React.forwardRef<
  HTMLDivElement,
  WithClassName<SheetPrimitive.Backdrop.Props>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Backdrop
    ref={ref}
    data-slot="sheet-overlay"
    className={cn(
      "fixed inset-0 z-50 bg-(--scrim)",
      "transition-opacity duration-base ease-out",
      "data-[starting-style]:opacity-0 data-[ending-style]:opacity-0",
      className,
    )}
    {...props}
  />
));
SheetOverlay.displayName = "SheetOverlay";

/**
 * Every sheet runs flush to its edge with square corners, like the rest of
 * the store's containers. It slides in from its side and eases out.
 */
const sheetVariants = cva(
  [
    "fixed z-50 flex flex-col gap-4 bg-background p-6 text-foreground shadow-(--shadow-overlay) outline-none",
    "transition-[translate,opacity] duration-base ease-out motion-reduce:transition-opacity",
    "",
  ].join(" "),
  {
    variants: {
      side: {
        top: "inset-x-0 top-0 max-h-[85vh] data-[starting-style]:-translate-y-full data-[ending-style]:-translate-y-full",
        bottom:
          "inset-x-0 bottom-0 max-h-[85vh] data-[starting-style]:translate-y-full data-[ending-style]:translate-y-full",
        left: "inset-y-0 left-0 h-full w-3/4 max-w-md data-[starting-style]:-translate-x-full data-[ending-style]:-translate-x-full",
        right:
          "inset-y-0 right-0 h-full w-3/4 max-w-md data-[starting-style]:translate-x-full data-[ending-style]:translate-x-full",
      },
    },
    defaultVariants: {
      side: "right",
    },
  },
);

interface SheetContentProps
  extends WithClassName<SheetPrimitive.Popup.Props>,
    VariantProps<typeof sheetVariants> {}

/**
 * Bold retail sheet panel: a white, square-edged panel on the overlay shadow.
 * A bottom sheet carries a grab handle, and a round grey button in the top
 * corner closes any sheet.
 */
const SheetContent = React.forwardRef<HTMLDivElement, SheetContentProps>(
  ({ side = "right", className, children, ...props }, ref) => (
    <SheetPortal>
      <SheetOverlay />
      <SheetPrimitive.Popup
        ref={ref}
        data-slot="sheet-content"
        data-side={side}
        className={cn(sheetVariants({ side }), className)}
        {...props}
      >
        {side === "bottom" && (
          <div
            aria-hidden="true"
            data-slot="sheet-handle"
            className="mx-auto -mt-2 h-1 w-10 shrink-0 rounded-full bg-border"
          />
        )}
        {children}
        <SheetPrimitive.Close
          data-slot="sheet-close"
          className={cn(
            buttonVariants({ variant: "secondary", size: "icon" }),
            "absolute end-4 top-4",
          )}
        >
          <Icon icon="mingcute:close-line" className="size-5" aria-hidden="true" />
          <span className="sr-only">Close</span>
        </SheetPrimitive.Close>
      </SheetPrimitive.Popup>
    </SheetPortal>
  ),
);
SheetContent.displayName = "SheetContent";

/** The title block at the top of a sheet. It leaves room for the close button. */
const SheetHeader = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="sheet-header"
    className={cn("flex flex-col gap-1.5 pe-12 text-start", className)}
    {...props}
  />
);
SheetHeader.displayName = "SheetHeader";

/** The action row, pinned to the foot of the sheet. Its buttons are pills. */
const SheetFooter = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="sheet-footer"
    className={cn(
      "mt-auto flex flex-col-reverse gap-2 sm:flex-row sm:justify-end",
      className,
    )}
    {...props}
  />
);
SheetFooter.displayName = "SheetFooter";

/** The sheet title: 1.5rem medium Inter in near-black. */
const SheetTitle = React.forwardRef<
  HTMLHeadingElement,
  WithClassName<SheetPrimitive.Title.Props>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Title
    ref={ref}
    data-slot="sheet-title"
    className={cn("font-sans text-2xl font-medium leading-tight text-foreground", className)}
    {...props}
  />
));
SheetTitle.displayName = "SheetTitle";

/** The supporting line under the title, in muted grey. */
const SheetDescription = React.forwardRef<
  HTMLParagraphElement,
  WithClassName<SheetPrimitive.Description.Props>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Description
    ref={ref}
    data-slot="sheet-description"
    className={cn("text-base text-muted-foreground", className)}
    {...props}
  />
));
SheetDescription.displayName = "SheetDescription";

export {
  Sheet,
  SheetPortal,
  SheetOverlay,
  SheetTrigger,
  SheetClose,
  SheetContent,
  SheetHeader,
  SheetFooter,
  SheetTitle,
  SheetDescription,
};
